<template><a-form><div v-if="errorMessage">{{errorMessage}}</div><a-form-item :label="t('observability_ui.forms.name')"><a-input v-model:value="form.name"/></a-form-item><a-form-item :label="t('observability_ui.forms.description')"><a-input v-model:value="form.description"/></a-form-item><a-form-item :label="t('observability_ui.forms.refresh')"><a-select v-model:value="form.refresh_interval_s" :options="refreshOptions"/></a-form-item><a-form-item :label="t('observability_ui.forms.time_range')"><a-select v-model:value="form.time_range" :options="rangeOptions"/></a-form-item><div v-for="(panel,index) in form.panels" :key="index"><a-form-item :label="t('observability_ui.forms.data_source')"><a-select v-model:value="panel.datasource_id" :options="datasourceOptions"/></a-form-item><a-form-item :label="t('observability_ui.forms.panel_title')"><a-input v-model:value="panel.title"/></a-form-item><a-form-item :label="t('observability_ui.forms.panel_type')"><a-select v-model:value="panel.panel_type" :options="typeOptions"/></a-form-item><a-form-item :label="t('observability_ui.forms.promql')"><a-input v-model:value="panel.promql"/></a-form-item><a-form-item :label="t('observability_ui.forms.unit')"><a-select v-model:value="panel.unit" :options="unitOptions"/></a-form-item><a-form-item :label="t('observability_ui.forms.legend')"><a-input v-model:value="panel.legend"/></a-form-item><a-form-item :label="t('observability_ui.forms.width')"><a-select v-model:value="panel.width" :options="widthOptions"/></a-form-item><a-button @click="move(index,-1)">{{t('common.up')}}</a-button><a-button @click="move(index,1)">{{t('common.down')}}</a-button><a-button @click="removePanel(index)">{{t('common.remove')}}</a-button></div><a-button @click="addPanel">{{t('observability_ui.dashboard.add_panel')}}</a-button><a-button :disabled="!valid" @click="save">{{t('common.save')}}</a-button></a-form></template>
<script setup lang="ts">
import{computed,inject,reactive,ref}from'vue';import{useI18n}from'@/hooks/useI18n';import type{ObservabilityDashboardApi}from'@/api/observability/dashboard';import type{Dashboard,NamedRef,PanelInput,SaveDashboard}from'@/types/observability'
const{t}=useI18n();const props=defineProps<{datasources:NamedRef[];initial?:Dashboard|null}>();const emit=defineEmits<{saved:[Dashboard]}>();const api=inject<ObservabilityDashboardApi|undefined>('observabilityDashboardApi');const form=reactive<SaveDashboard>({name:props.initial?.name??'',description:props.initial?.description??'',refresh_interval_s:props.initial?.refresh_interval_s??30,time_range:props.initial?.time_range??'1h',panels:props.initial?.panels.map(({datasource_id,title,panel_type,promql,unit,legend,sort_order,width})=>({datasource_id,title,panel_type,promql,unit,legend,sort_order,width}))??[]});const errorMessage=ref('')
const option=<T extends string|number>(values:readonly T[],prefix?:string)=>values.map(value=>({value,label:prefix?t(`${prefix}.${value}`):String(value)}));const typeOptions=option(['time_series','stat','table']as const,'observability_ui.panel_type');const unitOptions=option(['none','percent','bytes','bytes_per_second','cores','seconds','requests_per_second']as const,'observability_ui.units');const widthOptions=option([6,12]as const);const refreshOptions=option([15,30,60,300]as const);const rangeOptions=option(['15m','1h','6h','24h','7d']as const);const datasourceOptions=computed(()=>props.datasources.map(x=>({value:x.id,label:x.name})))
function addPanel(){const panel:PanelInput={datasource_id:0,title:t('observability_ui.dashboard.default_panel'),panel_type:'time_series',promql:'',unit:'none',legend:'',sort_order:form.panels.length,width:12};form.panels.push(panel)}function move(index:number,delta:number){const target=index+delta;if(target<0||target>=form.panels.length)return;const item=form.panels.splice(index,1)[0];if(item)form.panels.splice(target,0,item);form.panels.forEach((p,i)=>p.sort_order=i)}function removePanel(index:number){form.panels.splice(index,1);form.panels.forEach((panel,sortOrder)=>{panel.sort_order=sortOrder})}
const valid=computed(()=>!!form.name.trim()&&form.refresh_interval_s>0&&form.panels.length>0&&form.panels.every((p,i)=>p.datasource_id>0&&!!p.title.trim()&&!!p.promql.trim()&&p.sort_order===i&&['time_series','stat','table'].includes(p.panel_type)&&['none','percent','bytes','bytes_per_second','cores','seconds','requests_per_second'].includes(p.unit)&&[6,12].includes(p.width)));async function save(){if(!valid.value||!api){errorMessage.value=t('observability_ui.errors.invalid_dashboard');return}errorMessage.value='';const payload:SaveDashboard={...form,panels:form.panels.map((p,i)=>({...p,sort_order:i}))};try{const saved=props.initial?await api.update(props.initial.id,payload):await api.create(payload);emit('saved',saved)}catch(error){errorMessage.value=error instanceof Error?error.message:t('network.error')}}defineExpose({form,errorMessage,addPanel,move,removePanel,valid,save})
</script>
